package cn.zhuatech.searchai.service;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.assertThat;
class SearchIndexPublicationServiceTest{private final SearchIndexPublicationService s=new SearchIndexPublicationService();@Test void publishesTrustedIndex(){var r=s.assess(new SearchIndexPublicationService.Request("I1",true,true,true,true,true,92,85,3,10,true,true,true));assertThat(r.decision()).isEqualTo(SearchIndexPublicationService.Decision.PUBLISH);}@Test void canariesOperationalGaps(){var r=s.assess(new SearchIndexPublicationService.Request("I2",true,true,true,true,true,92,85,3,10,false,false,true));assertThat(r.actions()).hasSize(2);}@Test void blocksUnsafeIndex(){var r=s.assess(new SearchIndexPublicationService.Request("I3",false,false,false,false,false,50,85,20,10,true,true,false));assertThat(r.blockers()).hasSize(8);}}
